"""Minimal library-entry validator. Usage: python validate_entries.py <entry_dir> [<vault_root_for_links>]
Checks: frontmatter fields, required sections, confidence vocabulary + source ceiling, wikilink resolution.
Exit code 1 if any defect."""
import re, sys, pathlib

REQ_FIELDS = ["type", "kind", "domain", "book", "chapter", "topic", "category", "confidence", "ingest-tier", "created"]
REQ_SECTIONS = ["What it is", "Why it works", "When to apply", "When NOT to apply", "Example", "Related"]
ALLOWED_CONF = {"supported", "untested", "contested"}  # source ceiling = supported; 'proven' is forbidden here

entry_dir = pathlib.Path(sys.argv[1])
vault = pathlib.Path(sys.argv[2]) if len(sys.argv) > 2 else entry_dir
note_names = {p.stem for p in vault.rglob("*.md")}

defects = 0
files = [p for p in sorted(entry_dir.glob("*.md")) if p.name != "_book.md"]
for p in files:
    s = p.read_text(encoding="utf-8")
    m = re.match(r"^---\n(.*?)\n---\n", s, re.S)
    probs = []
    if not m:
        probs.append("missing frontmatter")
        fm = {}
    else:
        fm = dict(re.findall(r"^([\w-]+):\s*(.*)$", m.group(1), re.M))
        probs += [f"missing field '{f}'" for f in REQ_FIELDS if f not in fm]
    conf = fm.get("confidence", "").strip()
    if conf not in ALLOWED_CONF:
        probs.append(f"confidence '{conf}' not allowed (ceiling is supported)")
    for sec in REQ_SECTIONS:
        if not re.search(r"^\*\*" + re.escape(sec) + r"\*\*", s, re.M):
            probs.append(f"missing section '{sec}'")
    for link in re.findall(r"\[\[([^\]|#]+)", s):
        if link.strip() not in note_names:
            probs.append(f"dangling wikilink [[{link.strip()}]]")
    for pr in probs:
        print(f"{p.name}: {pr}")
    defects += len(probs)
print(f"checked {len(files)} file(s), {defects} defect(s)")
sys.exit(1 if defects else 0)

